// Keep bridge.vectors.json next to this file.
import Foundation
import XCTest
@testable import PlutoBridge

final class BridgeConformanceTests: XCTestCase {
    private struct Vector: Decodable {
        let name: String
        let json: String
        let nativeToWeb: String
        let webToNative: String
    }

    private func vectors() throws -> [Vector] {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("bridge.vectors.json")
        return try JSONDecoder().decode([Vector].self, from: Data(contentsOf: url))
    }

    func testVectors() throws {
        for v in try vectors() {
            let data = Data(v.json.utf8)
            let native = (try? Bridge.parseNativeToWeb(data)) != nil ? "accept" : "refuse"
            let web = (try? Bridge.parseWebToNative(data)) != nil ? "accept" : "refuse"
            if native != v.nativeToWeb { XCTFail("\(v.name): native-to-web gave \(native), expected \(v.nativeToWeb)") }
            if web != v.webToNative { XCTFail("\(v.name): web-to-native gave \(web), expected \(v.webToNative)") }
        }
    }

    func testCredentialsStayOutOfDescriptions() throws {
        for v in try vectors() where v.nativeToWeb == "accept" || v.webToNative == "accept" {
            let data = Data(v.json.utf8)
            let shown: String
            if v.nativeToWeb == "accept" { shown = "\(try Bridge.parseNativeToWeb(data)) \(String(reflecting: try Bridge.parseNativeToWeb(data)))" }
            else { shown = "\(try Bridge.parseWebToNative(data)) \(String(reflecting: try Bridge.parseWebToNative(data)))" }
            guard let root = try JSONSerialization.jsonObject(with: data) as? [String: Any], let payload = root["payload"] as? [String: Any] else { continue }
            for (key, value) in payload {
                guard let text = value as? String, key.range(of: "token|secret|password|credential", options: [.regularExpression, .caseInsensitive]) != nil else { continue }
                if shown.contains(text) { XCTFail("\(v.name): \(key) is printed") }
            }
        }
    }

    func testRoundTrips() throws {
        for v in try vectors() where v.nativeToWeb == "accept" || v.webToNative == "accept" {
            let data = Data(v.json.utf8)
            if v.nativeToWeb == "accept" {
                let message = try Bridge.parseNativeToWeb(data)
                let again = try? Bridge.parseNativeToWeb(Data(Bridge.encode(message).utf8))
                if again != message { XCTFail("roundtrip \(v.name)") } else { print("roundtrip ok \(v.name)") }
            } else {
                let message = try Bridge.parseWebToNative(data)
                let again = try? Bridge.parseWebToNative(Data(Bridge.encode(message).utf8))
                if again != message { XCTFail("roundtrip \(v.name)") } else { print("roundtrip ok \(v.name)") }
            }
        }
    }
}
